package propertyrental.platform.listing.application.mapper;

import org.springframework.stereotype.Component;

import propertyrental.platform.listing.api.dto.request.CreateUnitTypeRequest;
import propertyrental.platform.listing.api.dto.request.UpdateUnitTypeRequest;
import propertyrental.platform.listing.api.dto.response.UnitTypeResponse;
import propertyrental.platform.listing.infrastructure.persistence.entity.UnitTypeEntity;

@Component
public class UnitTypeMapper {

    // This builds a new entity from a create request (the id is generated by the database)
    public UnitTypeEntity toEntity(CreateUnitTypeRequest request) {
        UnitTypeEntity unitType = new UnitTypeEntity();
        unitType.setCode(request.code());
        unitType.setName(request.name());

        return unitType;
    }

    // This one applies an update request to an existing entity in place
    public void updateEntity(UnitTypeEntity unitType, UpdateUnitTypeRequest request) {
        unitType.setCode(request.code());
        unitType.setName(request.name());
    }

    // This convert an entity to the response DTO so that the entity is never exposed
    public UnitTypeResponse toResponse(UnitTypeEntity unitType) {

        return new UnitTypeResponse(
                unitType.getId(),
                unitType.getCode(),
                unitType.getName()
        );
    }
}